        const skMenuButton=document.querySelector('#sk-menu'),skNav=document.querySelector('#sk-nav');
        skMenuButton.addEventListener('click',()=>{const isOpen=skMenuButton.getAttribute('aria-expanded')==='true';skMenuButton.setAttribute('aria-expanded',String(!isOpen));skMenuButton.setAttribute('aria-label',isOpen?'Buka menu':'Tutup menu');skNav.classList.toggle('open',!isOpen)});
        skNav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{skNav.classList.remove('open');skMenuButton.setAttribute('aria-expanded','false');skMenuButton.setAttribute('aria-label','Buka menu')}));
        const skSafe=(tag,className,text)=>{const element=document.createElement(tag);if(className)element.className=className;element.textContent=text;return element};
        const skMoney=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0);
        const skBudgetYear=document.querySelector('#sk-budget-year'),skBudgetList=document.querySelector('#sk-budget-list'),skBudgetLabel=document.querySelector('#sk-budget-year-label');
        fetch('/api/desa/sumberkerang/budgets').then(response=>response.ok?response.json():Promise.reject()).then(budgets=>{if(!budgets.length)return;skBudgetYear.hidden=false;budgets.forEach(item=>{const option=document.createElement('option');option.value=item.year;option.textContent=String(item.year);skBudgetYear.append(option)});const render=()=>{const budget=budgets.find(item=>String(item.year)===String(skBudgetYear.value));if(!budget)return;skBudgetLabel.textContent=String(budget.year);skBudgetList.replaceChildren();[['Dana Desa',budget.villageFund],['Alokasi Dana Desa',budget.villageAllocation],['Bagi Hasil Pajak',budget.taxRevenueShare],['Bagi Hasil Retribusi',budget.retributionShare]].forEach(([label,value])=>{const row=document.createElement('div');row.className='sk-budget-row';row.append(skSafe('span','',label),skSafe('strong','',value?skMoney(value):'Belum tersedia'));skBudgetList.append(row)})};skBudgetYear.value=String(budgets[0].year);skBudgetYear.addEventListener('change',render);render()}).catch(()=>{});
        const skFilters=document.querySelector('#sk-project-filters'),skProjectCount=document.querySelector('#sk-project-count'),skProjectList=document.querySelector('#sk-project-list'),skFilterYear=document.querySelector('#sk-project-year'),skFilterStatus=document.querySelector('#sk-project-status'),skFilterLocation=document.querySelector('#sk-project-location');let skProjects=[];
        function skRenderProjects(){
            const filters=[['year',skFilterYear.value],['status',skFilterStatus.value],['location',skFilterLocation.value]];
            const visible=skProjects.filter(project=>filters.every(([key,value])=>!value||String(project[key]||'')===value));
            skProjectCount.textContent=`${visible.length} dari ${skProjects.length} kegiatan dan usulan`;
            skProjectList.replaceChildren();
            if(!visible.length){skProjectList.append(skSafe('p','sk-project-empty','Belum ada informasi pembangunan yang dapat ditampilkan.'));return}
            const formatProjectAmount=value=>{
                const amount=String(value??'').trim();
                if(!amount)return 'Belum tersedia';
                if(/^\d+$/.test(amount))return skMoney(Number(amount));
                return amount;
            };
            visible.forEach((project,index)=>{
                const row=document.createElement('article');row.className='sk-project';
                row.append(skSafe('span','sk-project-no',String(index+1).padStart(2,'0')));
                const content=document.createElement('div'),meta=document.createElement('div');meta.className='sk-project-meta';
                [project.year,project.location,project.status].filter(Boolean).forEach(value=>meta.append(skSafe('span','',String(value))));
                content.append(meta,skSafe('h3','',project.title||'Kegiatan desa'));
                const projectDescription=project.details||project.description;
                if(projectDescription)content.append(skSafe('p','',projectDescription));
                const end=document.createElement('div');end.className='sk-project-end';
                const budgetSummary=document.createElement('div');budgetSummary.className='sk-project-card-budget';budgetSummary.append(skSafe('span','','Anggaran'),skSafe('strong','',formatProjectAmount(project.summary)));end.append(budgetSummary);
                const detail=skSafe('button','sk-project-detail','Rincian pekerjaan');detail.type='button';detail.setAttribute('aria-expanded','false');
                const pop=document.createElement('div');pop.className='sk-project-pop';pop.id=`sk-project-details-${project.id??index}`;pop.setAttribute('role','dialog');pop.setAttribute('aria-label',`Rincian ${project.title||'kegiatan desa'}`);detail.setAttribute('aria-controls',pop.id);
                const head=document.createElement('div');head.className='sk-pop-head';head.append(skSafe('strong','','Rincian pekerjaan'));
                const close=skSafe('button','sk-pop-close','');close.type='button';close.setAttribute('aria-label','Tutup rincian');close.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 6 12 12M18 6 6 18"/></svg>';
                close.addEventListener('click',()=>{pop.classList.remove('open');detail.setAttribute('aria-expanded','false');detail.focus()});head.append(close);pop.append(head);
                const budget=document.createElement('div');budget.className='sk-pop-budget';budget.append(skSafe('span','','Anggaran'),skSafe('strong','',formatProjectAmount(project.summary)));pop.append(budget);
                const grid=document.createElement('div');grid.className='sk-pop-grid';
                const addRow=(label,value,wide=false)=>{const item=document.createElement('div');item.className=`sk-pop-row${wide?' is-wide':''}`;item.append(skSafe('span','',label),skSafe('strong','',value||'Belum tersedia'));grid.append(item)};
                addRow('Lokasi',project.location);addRow('Tahun',String(project.year||''));
                addRow('Status',project.status);addRow('Volume',project.volume);
                addRow('Sumber dana',project.funding);addRow('Pelaksana',project.executor);
                addRow('Jadwal',project.schedule);addRow('Progres fisik',project.progress==null?'':`${project.progress}%`);
                addRow('Realisasi belanja',skMoney(Number(project.spent)||0));
                pop.append(grid);
                const details=skSafe('p','sk-pop-detail',project.details||'Rincian pekerjaan belum tersedia.');pop.append(details);
                if(project.sourceUrl){const source=document.createElement('a');source.className='sk-pop-source';source.href=project.sourceUrl;source.target='_blank';source.rel='noopener noreferrer';source.textContent=project.source||'Sumber informasi';pop.append(source)}
                detail.addEventListener('click',()=>{
                    const shouldOpen=!pop.classList.contains('open');
                    document.querySelectorAll('.sk-project-pop.open').forEach(open=>{
                        open.classList.remove('open');
                        document.querySelector(`[aria-controls="${open.id}"]`)?.setAttribute('aria-expanded','false');
                    });
                    if(shouldOpen){pop.classList.add('open');detail.setAttribute('aria-expanded','true')}
                });
                row.append(content,end);end.append(detail);row.append(pop);skProjectList.append(row);
            });
        }
        fetch('/api/desa/sumberkerang/content').then(response=>response.ok?response.json():Promise.reject()).then(data=>{skProjects=Array.isArray(data.projects)?data.projects:[];if(!skProjects.length){skRenderProjects();return}[['year',skFilterYear],['status',skFilterStatus],['location',skFilterLocation]].forEach(([key,select])=>{[...new Set(skProjects.map(project=>String(project[key]||'')).filter(Boolean))].sort().forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option)})});skFilters.hidden=false;skProjectCount.hidden=false;skFilters.addEventListener('change',skRenderProjects);skFilters.addEventListener('reset',event=>{event.preventDefault();[skFilterYear,skFilterStatus,skFilterLocation].forEach(select=>select.value='');skRenderProjects()});skRenderProjects()}).catch(()=>{});
        const skQuestions=[{key:'title',prompt:'Apa usulan yang ingin disampaikan?',required:true,type:'text'},{key:'location',prompt:'Di mana usulan ini diperlukan?',required:true,type:'text'},{key:'category',prompt:'Pilih bidang usulan.',required:false,type:'choice',options:['Infrastruktur','Pertanian','Lingkungan','Sosial','Lainnya']},{key:'description',prompt:'Jelaskan usulan secara singkat.',required:true,type:'textarea'},{key:'name',prompt:'Nama (opsional).',required:false,type:'text'},{key:'contact',prompt:'Kontak yang bisa dihubungi (opsional).',required:false,type:'text'}];let skAnswers={},skStep=0;const skChat=document.querySelector('#sk-chat'),skMessages=document.querySelector('#sk-chat-messages'),skControls=document.querySelector('#sk-chat-controls'),skActions=document.querySelector('#sk-chat-actions'),skError=document.querySelector('#sk-chat-error'),skToggle=document.querySelector('#sk-chat-toggle');
        function skSay(text,isUser=false){skMessages.append(skSafe('div',`sk-chat-message${isUser?' is-user':''}`,text));skChat.querySelector('.sk-chat-body').scrollTop=skChat.querySelector('.sk-chat-body').scrollHeight}function skAction(label,handler,primary=false){const button=skSafe('button',primary?'primary':'',label);button.type='button';button.addEventListener('click',handler);return button}function skCloseChat(reset=true){skChat.classList.remove('open');skChat.setAttribute('aria-hidden','true');skToggle.setAttribute('aria-expanded','false');if(reset){skAnswers={};skStep=0;skMessages.replaceChildren();skControls.replaceChildren();skActions.replaceChildren();skError.textContent=''}}
        function skRenderQuestion(){skControls.replaceChildren();skActions.replaceChildren();skError.textContent='';if(skStep>=skQuestions.length){skSay('Periksa kembali usulan sebelum dikirim.');skSay(`${skAnswers.title}\n${skAnswers.location}\n${skAnswers.description}`);skActions.append(skAction('Batal',()=>skCloseChat()),skAction('Kirim usulan',skSubmitProposal,true));return}const question=skQuestions[skStep];skSay(question.prompt);skControls.append(skSafe('div','sk-chat-prompt',`${skStep+1} dari ${skQuestions.length}`));if(question.type==='choice'){const options=document.createElement('div');options.className='sk-chat-options';question.options.forEach(option=>options.append(skAction(option,()=>{skAnswers[question.key]=option;skSay(option,true);skStep++;skRenderQuestion()})));skControls.append(options)}else{const input=document.createElement(question.type==='textarea'?'textarea':'input');input.className='sk-chat-input';input.placeholder=question.key==='title'?'Judul usulan':question.key==='location'?'Lokasi':question.key==='description'?'Uraian singkat':question.key==='name'?'Nama':'Kontak';input.setAttribute('aria-label',input.placeholder);input.maxLength=question.key==='description'?3000:160;if(question.type==='textarea')input.rows=3;skControls.append(input)}skActions.append(skAction('Batal',()=>skCloseChat()));if(!question.required)skActions.append(skAction('Lewati',()=>{skAnswers[question.key]='';skStep++;skRenderQuestion()}));skActions.append(skAction(skStep===skQuestions.length-1?'Tinjau':'Lanjut',()=>{const input=skControls.querySelector('input,textarea'),value=input?.value.trim()||'';if(question.required&&!value){skError.textContent='Bagian ini perlu diisi.';return}skAnswers[question.key]=value;if(value)skSay(value,true);skStep++;skRenderQuestion()},true))}
        async function skSubmitProposal(){skError.textContent='';const send=skActions.querySelector('.primary');send.disabled=true;try{const response=await fetch('/api/desa/sumberkerang/proposals',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({...skAnswers,website:''})});const result=response.status===204?{}:await response.json();if(!response.ok)throw new Error(result.message||'Usulan belum berhasil dikirim.');skMessages.replaceChildren();skControls.replaceChildren();skActions.replaceChildren();skSay(result.message||'Usulan berhasil dikirim.');skActions.append(skAction('Selesai',()=>skCloseChat(),true))}catch(exception){skError.textContent=exception.message;send.disabled=false}}
        skToggle.addEventListener('click',()=>{const open=!skChat.classList.contains('open');skChat.classList.toggle('open',open);skChat.setAttribute('aria-hidden',String(!open));skToggle.setAttribute('aria-expanded',String(open));if(open&&!skMessages.childElementCount)skRenderQuestion()});document.querySelector('#sk-chat-close').addEventListener('click',()=>skCloseChat(false));
    </script>
    @include('desa.partials.managed-content')
    @include('desa.partials.responsive')
</body>
</html>
